import { useState, useEffect } from 'react';

export function OrderList() {
  const [orders, setOrders] = useState([]);

  useEffect(() => {
    fetch('/api/orders')
      .then(res => res.json())
      .then(data => setOrders(data));
  }, []);

  return (
    <ul>
      {orders.map((order, i) => (
        <li key={i}>{order.label}</li>
      ))}
    </ul>
  );
}
